<?php
$c=cart();if(!$c)redirect('shop');$marks=implode(',',array_fill(0,count($c),'?'));$s=db()->prepare("SELECT * FROM shop_products WHERE id IN ($marks)");$s->execute(array_keys($c));$products=$s->fetchAll();$total=0;foreach($products as &$p){$p['qty']=$c[$p['id']];$total+=$p['qty']*$p['price'];}unset($p);
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(!$name||!$phone)throw new RuntimeException('نام و شماره تماس الزامی است.');$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO shop_orders (customer_name,phone,address,total,status,created_at) VALUES (?,?,?,?, 'demo_pending',UTC_TIMESTAMP())");$q->execute([$name,$phone,$address,$total]);$oid=$pdo->lastInsertId();$qi=$pdo->prepare('INSERT INTO shop_order_items (order_id,product_id,product_name,price,qty) VALUES (?,?,?,?,?)');foreach($products as $p)$qi->execute([$oid,$p['id'],$p['name'],$p['price'],$p['qty']]);$pdo->commit();$_SESSION['cart']=[];page_header('ثبت سفارش','shop');echo '<section class="shop-wrap"><div class="shell"><div class="empty"><h2>سفارش دمو ثبت شد</h2><p>شماره سفارش شما: #'.e($oid).'</p><p>درگاه پرداخت در حالت آزمایشی است و بعداً می‌توان درگاه ایرانی به آن متصل کرد.</p><a class="btn btn-gold" href="'.url('shop').'">بازگشت به فروشگاه</a></div></div></section>';page_footer();exit;}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
page_header('تسویه حساب','shop');
?>
<section class="shop-wrap"><div class="shell checkout"><form method="post" class="form-card"><h2>اطلاعات سفارش</h2><?php if(!empty($error)):?><div class="notice"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="field"><label>نام و نام خانوادگی</label><input name="name" required></div><div class="field"><label>شماره تماس</label><input name="phone" dir="ltr" required></div><div class="field"><label>آدرس</label><textarea name="address" rows="5"></textarea></div><button class="form-btn" style="background:var(--gold);color:#0a0908">ثبت سفارش آزمایشی</button></form><aside class="form-card"><h2>خلاصه سفارش</h2><?php foreach($products as $p):?><p style="display:flex;justify-content:space-between"><span><?=e($p['name'])?> × <?=$p['qty']?></span><span><?=money($p['qty']*$p['price'])?></span></p><?php endforeach;?><hr style="border-color:var(--line)"><h3>جمع: <?=money($total)?></h3><p style="color:var(--muted);font-size:.75rem">پرداخت در این مرحله دمو است.</p></aside></div></section>
<?php page_footer(); ?>
